// 间接访问
printf("%d", *p);

int a = 10;
int *p = &a;
printf("%d", *p); // 输出 10

#include <stdio.h>

int main() {
    int arr[5] = {10, 20, 30, 40, 50};
    int *p = arr; // 指针指向数组首元素

    printf("使用指针遍历数组：\n");
    for (int i = 0; i < 5; i++) {
        printf("arr[%d] = %d\n", i, *p);
        p++; // 指针移动到下一个元素
    }
    return 0;
}

